const sumImageBytesByTenant = `-- name: SumImageBytesByTenant :one
SELECT coalesce(sum(i.byte_size), 0)::bigint FROM images i
JOIN restaurants r ON r.id = i.restaurant_id
WHERE r.tenant_id = $1 AND i.status = 'ready'
`

// Storage counts only images that made it to 'ready': a pending row has no
// bytes in the bucket yet, and a failed one had its object removed.
func (q *Queries) SumImageBytesByTenant(ctx context.Context, tenantID uuid.UUID) (int64, error) {
	row := q.db.QueryRow(ctx, sumImageBytesByTenant, tenantID)
	var column_1 int64
	err := row.Scan(&column_1)
	return column_1, err
}

const suspendPastDueSubscriptions = `-- name: SuspendPastDueSubscriptions :many
UPDATE subscriptions
SET status = 'suspended'
WHERE status = 'past_due'
  AND current_period_end IS NOT NULL
  AND current_period_end < now() - make_interval(secs => $1::double precision)
RETURNING id, tenant_id, plan_code, status, provider, provider_ref, current_period_start, current_period_end, cancel_at_period_end, cancelled_at, created_at, updated_at
`

// The second half: an unpaid subscription that has also used up its grace is
// suspended. Suspension freezes the tenant's own writes; it does not touch the
// public menu or a guest's order in progress.
func (q *Queries) SuspendPastDueSubscriptions(ctx context.Context, graceSeconds float64) ([]Subscription, error) {
	rows, err := q.db.Query(ctx, suspendPastDueSubscriptions, graceSeconds)
	if err != nil {
		return nil, err
	}
	defer rows.Close()
	items := []Subscription{}
	for rows.Next() {
		var i Subscription
		if err := rows.Scan(
			&i.ID,
			&i.TenantID,
			&i.PlanCode,
			&i.Status,
			&i.Provider,
			&i.ProviderRef,
			&i.CurrentPeriodStart,
			&i.CurrentPeriodEnd,
			&i.CancelAtPeriodEnd,
			&i.CancelledAt,
			&i.CreatedAt,
			&i.UpdatedAt,
		); err != nil {
			return nil, err
		}
		items = append(items, i)
	}
	if err := rows.Err(); err != nil {
		return nil, err
	}
	return items, nil
}
